import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';


export type BlurredListProps = Record<string, any>;

const BlurredList: React.FC<BlurredListProps> = ({
  backgroundColor = "#0a0a0b",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "THE 3 REASONS WHY YOU'RE HERE RIGHT NOW...",
  titleColor = "#ffffff",
  points = [
    "You demand high-performance animations",
    "You want seamless workflow integration",
    "You appreciate pixel-perfect precision"
  ],
  pointColor = "#e2e8f0",
  accentColor = "#3b82f6",
  staggerDelay = 30,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background logic safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animation Interpolations
  const titleOpacity = interpolate(frame, [10, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleTranslateY = interpolate(frame, [10, 35], [50, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleBlur = interpolate(frame, [10, 35], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: '"Futura", sans-serif',
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: `${height * 0.1}px ${width * 0.1}px`,
      }}
    >
      {/* Title Section */}
      <div
        style={{
          opacity: titleOpacity,
          transform: `translateY(${titleTranslateY}px)`,
          filter: `blur(${titleBlur}px)`,
          marginBottom: height * 0.12,
          textAlign: "center",
          maxWidth: width * 0.7,
          transition: "none",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: Math.min(width, height) * 0.055,
            fontWeight: "bold",
            color: titleColor,
            lineHeight: 1.2,
            letterSpacing: "-0.02em",
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {titleText}
        </h1>
      </div>

      {/* Points List Section */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: height * 0.06,
          width: "100%",
          maxWidth: width * 0.65,
        }}
      >
        {points.map((point, index) => {
          // Staggered timing for each point
          const startFrame = 30 + index * staggerDelay;
          
          // Determine physics-based reveal
          const pointSpring = spring({
            frame: Math.max(0, frame - startFrame),
            fps,
            config: {
              damping: 14,
              stiffness: 90,
              mass: 0.8,
            },
          });

          // Interpolate visual properties derived from spring and frame
          const translateY = interpolate(pointSpring, [0, 1], [40, 0]);
          const scale = interpolate(pointSpring, [0, 1], [0.95, 1]);
          const opacity = interpolate(frame - startFrame, [0, 20], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          
          const blurAmount = interpolate(frame - startFrame, [0, 25], [24, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          return (
            <div
              key={`point-${index}`}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                filter: `blur(${blurAmount}px)`,
                backgroundColor: `${pointColor}0A`,
                padding: `${height * 0.03}px ${width * 0.03}px`,
                borderRadius: height * 0.02,
                border: `1px solid ${pointColor}1A`,
                transition: "none",
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  minWidth: width * 0.04,
                  height: width * 0.04,
                  borderRadius: "50%",
                  backgroundColor: `${accentColor}20`,
                  color: accentColor,
                  fontSize: Math.min(width, height) * 0.035,
                  fontWeight: "bold",
                  marginRight: width * 0.03,
                  transition: "none",
                }}
              >
                {index + 1}
              </div>
              <p
                style={{
                  margin: 0,
                  fontSize: Math.min(width, height) * 0.04,
                  fontWeight: "bold",
                  color: pointColor,
                  lineHeight: 1.4,
                  transition: "none",
                }}
              >
                {point}
              </p>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default BlurredList;